const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const html = new TextDecoder('euc-kr').decode(buf);

const kst = new Date(Date.now() + 9 * 3600 * 1000);
const today = Date.UTC(kst.getUTCFullYear(), kst.getUTCMonth(), kst.getUTCDate());
const weekEnd = today + 6 * 86400000;
const fmt = (t) => { const d = new Date(t); return String(d.getUTCMonth() + 1).padStart(2, '0') + '/' + String(d.getUTCDate()).padStart(2, '0'); };

const clean = (s) => s.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').trim();
const all = [];
for (const r of html.matchAll(/<tr bgcolor='#[0-9A-Fa-f]+'>([\s\S]*?)<\/tr>/g)) {
  const c = [...r[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(m => clean(m[1]));
  const m = (c[1] || '').match(/(\d{4})\.(\d{2})\.(\d{2})~(\d{2})\.(\d{2})/);
  if (!m) continue;
  const y = +m[1];
  const start = Date.UTC(y, +m[2] - 1, +m[3]);
  const end = Date.UTC(+m[4] < +m[2] ? y + 1 : y, +m[4] - 1, +m[5]);
  const fixed = c[2] && c[2] !== '-' ? '확정 ' + c[2] : '희망 ' + (c[3] || '-');
  const rate = c[4] ? ' 경쟁률 ' + c[4] : '';
  all.push({ name: c[0], start, end, line: `${c[0]} ${fmt(start)}~${fmt(end)} ${fixed}${rate}` });
}
all.sort((a, b) => a.start - b.start);

let picked = all.filter(x => x.end >= today && x.start <= weekEnd);
let header = `📈 이번 주 공모주 (${fmt(today)}~${fmt(weekEnd)})`;
if (picked.length === 0) {
  picked = all.filter(x => x.start > weekEnd);
  header = `📈 이번 주 청약 없음 - 다가오는 공모주 (${fmt(today)} 기준)`;
}
picked = picked.slice(0, 10);
if (picked.length === 0) return [{ json: { text: '📈 조회된 공모주 일정이 없습니다.' } }];

// 카카오 text 템플릿은 200자 제한 → 분할
const lines = picked.map((x, i) => `${i + 1}. ${x.line}`);
const chunks = [];
let cur = header;
for (const l of lines) {
  if ((cur + '\n' + l).length > 190) { chunks.push(cur); cur = l; }
  else cur += '\n' + l;
}
chunks.push(cur);
return chunks.map(text => ({ json: { text } }));

